15	
16	/**
17	 * Drives the flow. Every screen is handed its slice of the store and a way
18	 * forward; none of them knows what comes next, which is what makes reordering
19	 * FLOW enough to reorder the product.
20	 */
21	export function Onboarding({ onFinished }: { onFinished: () => void }) {
22	  const { state, step, patch, hydrate, next, back, goTo } = useOnboardingStore();
23	  const { session } = useAuth();
24	  const [authMode, setAuthMode] = useState<'signin' | 'signup'>('signup');
25	  const [picks, setPicks] = useState<Recommendation[]>([]);
26	
27	  /* direction drives the slide; back slides the other way */
28	  const prev = useRef<Step>(step);
29	  const [dir, setDir] = useState<'fwd' | 'back'>('fwd');
30	  useEffect(() => {
31	    if (prev.current !== step) {
32	      setDir(FLOW.indexOf(step) >= FLOW.indexOf(prev.current) ? 'fwd' : 'back');
33	      prev.current = step;
34	    }
35	  }, [step]);
36	
37	  /* signing in mid-flow moves past the auth screens on its own */
38	  useEffect(() => {
39	    if (session && (step === 'auth-choice' || step === 'auth-form')) {
40	      patch({ auth: { userId: session.user.id, email: session.user.email ?? null } });
41	      goTo(FLOW.indexOf('profile'));
42	    }
43	    // eslint-disable-next-line react-hooks/exhaustive-deps
44	  }, [session, step]);
45	
46	  /* Answers given on another device live on the profile row, not in this
47	     device's localStorage. Read them back once so a returning user is not
48	     asked the same three questions again. */
49	  const hydrated = useRef(false);
50	  useEffect(() => {
51	    const userId = session?.user.id;
52	    if (!userId || hydrated.current) return;
53	    hydrated.current = true;
54	    getProfile(userId)
55	      .then((p) =>
56	        hydrate({
57	          diet: p.diet,
58	          reactions: p.reactions,
59	          reactionsNote: p.reactions_note,
60	          forms: p.form_prefs,
61	        }),
62	      )
63	      .catch(() => {});
64	  }, [session, hydrate]);
65	
66	  const finish = async () => {
67	    const userId = session?.user.id;
68	    if (userId) {
69	      // everything collected that the app proper actually reads
70	      await updateProfile(userId, {
71	        wake_time: state.wake,
72	        sleep_time: state.sleep,
73	        // the supplement sheet reads these to personalise the intake
74	        age: state.profile.age,
75	        sex: state.profile.gender,
76	      }).catch(() => {});
77	      /* Written on its own, because these columns arrive with migration 0018
78	         and a database that has not run it yet must still keep the age, sex
79	         and waking window above — one update carrying all of it would lose
80	         the lot to a single unknown column. */
81	      await updateProfile(userId, {
82	        diet: state.diet,
83	        reactions: state.reactions,
84	        reactions_note: state.reactionsNote.trim() || null,
85	        form_prefs: state.forms,
86	      }).catch(() => {});
87	      for (const item of state.schedule) {
88	        const rec = picks.find((p) => p.id === item.id);
89	        if (!rec) continue;
90	        await addScheduleItem(userId, {
91	          name: rec.name,
92	          // the person's own reference intake where one exists; blank means
93	          // there is no established amount and they set it themselves
94	          amount: rec.amount,
95	          scheduled_time: `${item.time}:00`,
96	          glossary_id: rec.id,
97	          start_date: toISODate(new Date()),
98	        }).catch(() => {});
99	      }
100	    }
