102	    onFinished();
103	  };
104	
105	  const skip = () => {
106	    if (step === 'q1') patch({ survey: { ...state.survey, q1: null } });
107	    if (step === 'q2') patch({ survey: { ...state.survey, q2: null } });
108	    if (step === 'q3') patch({ survey: { ...state.survey, q3: null } });
109	    // an empty answer is a real answer on these three: it means no preference
110	    if (step === 'diet') patch({ diet: [] });
111	    if (step === 'reactions') patch({ reactions: [], reactionsNote: '' });
112	    if (step === 'forms') patch({ forms: [] });
113	    next();
114	  };
115	
116	  const body = (() => {
117	    switch (step) {
118	      case 'welcome':
119	        return <Welcome onNext={next} />;
120	
121	      case 'auth-choice':
122	        return (
123	          <AuthChoice
124	            onEmail={() => {
125	              setAuthMode('signup');
126	              next();
127	            }}
128	            onSignIn={() => {
129	              setAuthMode('signin');
130	              next();
131	            }}
132	          />
133	        );
134	
135	      case 'auth-form':
136	        return (
