170	            onNext={next}
171	          />
172	        );
173	
174	      case 'info-library':
175	      case 'info-recs':
176	        return <Info which={step} onNext={next} />;
177	
178	      case 'q1':
179	      case 'q2':
180	      case 'q3':
181	        return (
182	          <SurveyScreen
183	            question={QUESTIONS[step]}
184	            value={state.survey[step]}
185	            onPick={(v) =>
