1	import { useEffect, useRef, useState } from 'react';
2	import { Cta, OnboardIllustration, Screen, Sub, Title } from '../chrome';
3	
4	/* ── profile ─────────────────────────────────────────────────────────── */
5	
6	const MIN_AGE = 13;
7	const MAX_AGE = 99;
8	/** px between year ticks on the ruler */
9	const TICK = 14;
10	
11	export function Profile({
12	  age,
13	  gender,
14	  onChange,
15	  onNext,
16	}: {
17	  age: number | null;
18	  gender: 'm' | 'f' | 'na' | null;
19	  onChange: (p: { age?: number; gender: 'm' | 'f' | 'na' | null }) => void;
20	  onNext: () => void;
21	}) {
22	  const value = age ?? 25;
23	  const set = (n: number) => onChange({ age: Math.round(Math.min(MAX_AGE, Math.max(MIN_AGE, n))), gender });
24	
25	  const drag = useRef<{ x: number; start: number } | null>(null);
26	  const [width, setWidth] = useState(320);
27	  const railRef = useRef<HTMLDivElement>(null);
28	
29	  useEffect(() => {
30	    const measure = () => railRef.current && setWidth(railRef.current.clientWidth);
31	    measure();
32	    window.addEventListener('resize', measure);
33	    return () => window.removeEventListener('resize', measure);
34	  }, []);
35	
36	  const onDown = (e: React.PointerEvent) => {
37	    drag.current = { x: e.clientX, start: value };
38	    (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);
39	  };
40	  const onMove = (e: React.PointerEvent) => {
41	    if (!drag.current) return;
42	    set(drag.current.start - (e.clientX - drag.current.x) / TICK);
43	  };
44	  const onUp = () => {
45	    drag.current = null;
46	  };
47	
48	  // enough ticks either side to fill the rail, clipped to the real range
49	  const half = Math.ceil(width / TICK / 2) + 1;
50	  const ticks: number[] = [];
51	  for (let y = value - half; y <= value + half; y++) if (y >= MIN_AGE && y <= MAX_AGE) ticks.push(y);
52	
53	  return (
54	    <Screen scroll footer={<Cta onClick={onNext}>Continue</Cta>}>
55	      <Title>About you</Title>
56	      <Sub>Dose ranges differ by age and sex. This stays on your device.</Sub>
57	
58	      <div className="ob-age">
59	        <div className="ob-age-num">
60	          {value}
61	          <span className="ob-age-unit">yrs</span>
62	        </div>
63	
64	        <div
65	          className="ob-ruler"
66	          ref={railRef}
67	          onPointerDown={onDown}
68	          onPointerMove={onMove}
69	          onPointerUp={onUp}
70	          onPointerCancel={onUp}
71	          role="slider"
72	          tabIndex={0}
73	          aria-label="Age"
74	          aria-valuemin={MIN_AGE}
75	          aria-valuemax={MAX_AGE}
76	          aria-valuenow={value}
77	          onKeyDown={(e) => {
78	            if (e.key === 'ArrowLeft') set(value - 1);
79	            if (e.key === 'ArrowRight') set(value + 1);
80	          }}
81	        >
82	          {ticks.map((y) => {
83	            const major = y % 5 === 0;
84	            return (
85	              <span key={y}>
86	                <span
87	                  className={`ob-ruler-mark${major ? ' major' : ''}`}
88	                  style={{ left: width / 2 + (y - value) * TICK, height: major ? 22 : 13 }}
89	                />
90	                {major && (
91	                  <span className="ob-ruler-label" style={{ left: width / 2 + (y - value) * TICK }}>
92	                    {y}
93	                  </span>
94	                )}
95	              </span>
96	            );
97	          })}
98	          <span className="ob-ruler-needle" />
99	        </div>
100	
101	        <div className="ob-age-steppers">
102	          <button className="ob-stepper" onClick={() => set(value - 1)} aria-label="One year younger">
103	            <svg width="16" height="16" viewBox="0 0 16 16" stroke="currentColor" strokeWidth="1.9" strokeLinecap="round" aria-hidden>
104	              <path d="M3.5 8h9" />
105	            </svg>
106	          </button>
107	          <button className="ob-stepper" onClick={() => set(value + 1)} aria-label="One year older">
108	            <svg width="16" height="16" viewBox="0 0 16 16" stroke="currentColor" strokeWidth="1.9" strokeLinecap="round" aria-hidden>
109	              <path d="M8 3.5v9M3.5 8h9" />
110	            </svg>
111	          </button>
112	        </div>
113	      </div>
114	
115	      <div className="ob-pill-row" style={{ marginTop: 30 }}>
116	        {([['m', 'Male'], ['f', 'Female'], ['na', 'Prefer not to say']] as const).map(([id, label]) => (
117	          <button
118	            key={id}
119	            className={`ob-pill${gender === id ? ' on' : ''}`}
120	            aria-pressed={gender === id}
121	            onClick={() => onChange({ age: value, gender: id })}
122	          >
123	            {label}
124	          </button>
125	        ))}
126	      </div>
127	    </Screen>
128	  );
129	}
