290	/** Toggling one option, with the clear-all and the implications applied. */
291	export function toggleMulti(q: MultiQuestion, value: string[], id: string): string[] {
292	  const order = (v: string[]) =>
293	    q.options.map((o) => o.id).filter((o) => v.includes(o));
294	
295	  if (id === q.clears) return value.includes(id) ? [] : [id];
296	
297	  // picking anything real retires the clear-all option
298	  const rest = value.filter((v) => v !== q.clears);
299	
300	  if (rest.includes(id)) {
301	    // turning one off also turns off whatever implied it, rather than leaving
302	    // behind a pair of answers that contradict each other
303	    const implied = Object.entries(q.implies ?? {})
304	      .filter(([, ids]) => ids.includes(id))
305	      .map(([key]) => key);
306	    return order(rest.filter((v) => v !== id && !implied.includes(v)));
307	  }
308	
309	  return order([...rest, id, ...(q.implies?.[id] ?? [])]);
310	}
