386	}: {
387	  question: Question;
388	  value: string | null;
389	  onPick: (v: string) => void;
390	  onNext: () => void;
391	}) {
392	  return (
393	    <Screen
394	      scroll
395	      footer={
396	        <Cta onClick={onNext} disabled={value === null}>
397	          Continue
398	        </Cta>
399	      }
400	    >
401	      <Title>{question.title}</Title>
402	      <Sub>{question.sub}</Sub>
403	
404	      <div className="ob-options" role="radiogroup" aria-label={question.title}>
405	        {question.options.map((o) => (
406	          <button
407	            key={o.id}
408	            role="radio"
409	            aria-checked={value === o.id}
410	            className={`ob-option${value === o.id ? ' on' : ''}`}
411	            onClick={() => onPick(o.id)}
412	          >
413	            {o.label}
