1	import { useEffect, useRef, useState } from 'react';
2	import { animate, motion, useMotionValue, useTransform } from 'framer-motion';
3	import { Cta, Screen } from '../chrome';
4	import { GOALS } from '../goals';
5	
6	const SPRING = { type: 'spring' as const, stiffness: 260, damping: 30, mass: 0.9 };
7	/** commit to the drag inside this many px */
8	const THRESHOLD = 8;
9	const RUBBER = 0.35;
10	/**
11	 * How far a flick carries, in seconds of projected travel. The Action Button
12	 * picker lets a hard swipe run several items rather than always landing on the
13	 * neighbour, so the release is projected well past the finger and only then
14	 * rounded — 0.2s stopped at the next card no matter how hard you threw it.
15	 */
16	const FLICK_PROJECTION = 0.75;
17	/** a slow drag still needs a small nudge to count */
18	const MIN_FLICK = 0.35;
19	/** px of travel per card, so neighbours sit just off-centre */
20	const SPREAD = 250;
21	
22	/**
23	 * The Action Button picker.
24	 *
25	 * One goal fills the screen; the icon, the name, the copy and the dots are all
26	 * pure functions of a single continuous `pos` value, so a half-finished drag
27	 * shows a half-finished transition rather than snapping at the end. Tap the
28	 * glyph to select, drag or swipe to page.
29	 */
30	export function Goals({
31	  selected,
32	  onChange,
33	  onNext,
34	}: {
35	  selected: string[];
36	  onChange: (v: string[]) => void;
37	  onNext: () => void;
38	}) {
39	  const [index, setIndex] = useState(0);
40	  const pos = useMotionValue(0);
41	  const width = useRef(320);
42	  const hostRef = useRef<HTMLDivElement>(null);
43	
44	  useEffect(() => {
45	    const measure = () => hostRef.current && (width.current = hostRef.current.clientWidth);
46	    measure();
47	    window.addEventListener('resize', measure);
48	    return () => window.removeEventListener('resize', measure);
49	  }, []);
50	
51	  const drag = useRef({ active: false, axis: null as null | 'x' | 'y', x: 0, y: 0, start: 0, vel: 0, t: 0 });
52	
53	  const goTo = (i: number, velocity = 0) => {
54	    const t = Math.max(0, Math.min(GOALS.length - 1, i));
55	    setIndex(t);
56	    animate(pos, t, { ...SPRING, velocity });
57	  };
58	
59	  const onPointerDown = (e: React.PointerEvent) => {
60	    if (e.pointerType === 'mouse' && e.button !== 0) return;
61	    pos.stop();
62	    drag.current = { active: true, axis: null, x: e.clientX, y: e.clientY, start: pos.get(), vel: 0, t: performance.now() };
63	  };
64	
65	  const onPointerMove = (e: React.PointerEvent) => {
66	    const d = drag.current;
67	    if (!d.active) return;
68	    const dx = e.clientX - d.x;
69	    const dy = e.clientY - d.y;
70	    if (d.axis === null) {
71	      if (Math.abs(dx) > THRESHOLD && Math.abs(dx) > Math.abs(dy)) {
72	        d.axis = 'x';
73	        (e.currentTarget as HTMLElement).setPointerCapture?.(e.pointerId);
74	      } else if (Math.abs(dy) > THRESHOLD) {
75	        d.active = false;
76	        return;
