1	import { useEffect, useMemo, useRef, useState } from 'react';
2	import { Cta, OnboardIllustration, Screen, Sub, Title } from '../chrome';
3	import { GOAL_BY_ID, DEFAULT_GOAL_IDS } from '../goals';
4	import {
5	  getNutrientReference,
6	  listGlossary,
7	  type GlossaryEntry,
8	  type NutrientReference,
9	} from '../../lib/api';
10	import { checkPlacement, fromMinutes, toMinutes, type ScheduledItem } from '../../lib/conflicts';
