64	/** The Today arc, drawing itself. */
65	function DrawingArc() {
66	  const R = 150;
67	  const SWEEP = 88;
68	  const HALF = SWEEP / 2;
69	  const W = 220;
70	  const CX = W / 2;
71	  const CY = R + 7;
72	  const H = Math.ceil(R * (1 - Math.cos((HALF * Math.PI) / 180)) + 14);
73	  const pt = (deg: number) => {
74	    const r = (deg * Math.PI) / 180;
75	    return [CX + R * Math.sin(r), CY - R * Math.cos(r)];
76	  };
77	  const [a1, b1] = pt(-HALF);
78	  const [a2, b2] = pt(HALF);
79	  const d = `M${a1.toFixed(1)} ${b1.toFixed(1)} A${R} ${R} 0 0 1 ${a2.toFixed(1)} ${b2.toFixed(1)}`;
80	  return (
81	    <svg width={W} height={H} viewBox={`0 0 ${W} ${H}`} fill="none" aria-hidden>
82	      <path d={d} stroke="var(--card)" strokeWidth="9" strokeLinecap="round" />
83	      <path className="ob-arc-draw" d={d} stroke="var(--accent)" strokeWidth="9" strokeLinecap="round" pathLength={1} />
84	    </svg>
85	  );
86	}
87	
88	/* ── recommendations ─────────────────────────────────────────────────── */
89	
90	export interface Recommendation {
91	  id: string;
92	  name: string;
93	  why: string;
94	  route: string;
95	  selected: boolean;
96	  /** the intake that applies to this person, where a single figure does */
97	  amount: string;
98	  /**
99	   * Iron, for someone we have not been told about: both figures rather than a
100	   * guess between them. Display only — `amount` stays empty, so the schedule
101	   * stores no number, the same as anything else with no single established
102	   * figure. See lib/intake.ts.
103	   */
104	  amountRange: { yes: string; no: string } | null;
105	  /** a reaction they told us about put this one on a full stomach */
106	  withFood: boolean;
107	}
108	
109	/**
110	 * The reference figure with whatever adjustment a rule made to it. Rounded to
111	 * a whole number once it is big enough for a decimal to be noise — the
112	 * vegetarian iron figure lands on 32 mg and 14 mg, which is how ODS quotes it,
113	 * rather than 32.4 and 14.4.
114	 */
115	const scaled = (rda: number, factor: number) => {
116	  const v = rda * factor;
117	  return v >= 10 ? Math.round(v) : Math.round(v * 10) / 10;
118	};
119	
120	const doseLine = (r: Recommendation) =>
121	  [
122	    r.amountRange
123	      ? `${r.amountRange.yes} a day if you menstruate · ${r.amountRange.no} if you don’t · ${r.route}`
124	      : r.amount
125	        ? `${r.amount} a day · ${r.route}`
126	        : `${r.route} · you set the amount`,
127	    r.withFood ? 'with food' : null,
128	  ]
129	    .filter(Boolean)
130	    .join(' · ');
131	
132	export function useRecommendations(
133	  goalIds: string[],
134	  currentStack: string[],
135	  diet: string[],
136	  reactions: string[],
137	  forms: string[],
138	  age?: number | null,
139	  sex?: 'm' | 'f' | 'na' | null,
140	) {
141	  const [entries, setEntries] = useState<GlossaryEntry[] | null>(null);
142	  const [refs, setRefs] = useState<Record<string, NutrientReference[]>>({});
143	  useEffect(() => {
144	    /* Both in one update, deliberately. `Recommendations` below snapshots the
145	       cards the first render this returns anything, so entries arriving a
146	       round trip ahead of the reference intakes meant every card was built
147	       with no figure and read "you set the amount" — the amounts were only
148	       ever going to lose that race against a real server. */
149	    listGlossary(200)
150	      .then(async (rows) => {
151	        const refs = await getNutrientReference(rows.map((r) => r.id));
152	        setRefs(refs);
153	        setEntries(rows);
154	      })
155	      .catch(() => setEntries([]));
156	  }, []);
157	
158	  return useMemo(() => {
159	    if (!entries) return null;
160	    const ids = goalIds.length ? goalIds : DEFAULT_GOAL_IDS;
161	    const goalNames = ids.map((g) => GOAL_BY_ID[g]?.name ?? g);
162	
163	    /* Everything the ordering knows is in lib/recommend.ts, including the
164	       sentence on each card. This screen picks how many to show and turns a
165	       reference intake into a string; it does not decide anything. */
166	    const result = recommend(entries, {
167	      goalTags: ids.flatMap((g) => GOAL_BY_ID[g]?.tags ?? []),
168	      goalLabel: goalNames.length > 1 ? 'your goals' : (goalNames[0]?.toLowerCase() ?? 'your goals'),
169	      currentStack,
170	      diet,
171	      reactions,
172	      forms,
173	    });
174	
175	    return {
176	      picks: result.ranked.slice(0, 6).map((s, i) => {
177	        /* Onboarding never passes a menstrual status: it is not asked here,
178	           deliberately, so iron arrives as two figures and the question waits
179	           until the iron entry itself. */
180	        const intake = resolveIntake(s.entry, refs[s.entry.id], age, sex, null);
181	        const figure = (rda: number) => `${scaled(rda, s.amountFactor)} ${intake.unit}`;
182	        return {
183	          id: s.entry.id,
184	          name: s.entry.name,
185	          route: s.entry.route,
186	          amount: intake.rda != null && intake.rdaIfNot == null ? figure(intake.rda) : '',
187	          amountRange:
188	            intake.rda != null && intake.rdaIfNot != null
189	              ? { yes: figure(intake.rda), no: figure(intake.rdaIfNot) }
190	              : null,
191	          why: s.reason,
192	          withFood: s.timing === 'with_food',
193	          selected: i < 3,
194	        } satisfies Recommendation;
195	      }),
196	      leftOut: {
197	        alreadyTaking: result.alreadyTaking,
198	        swapped: result.swappedOut,
199	        noMatch: result.ranked.slice(6).map((s) => s.entry.name),
200	        goalNames,
201	      },
202	    };
203	  }, [entries, refs, goalIds, currentStack, diet, reactions, forms, age, sex]);
204	}
