15	  onDone: (granted: boolean) => void;
16	}) {
17	  const [busy, setBusy] = useState(false);
18	
19	  const ask = async () => {
20	    setBusy(true);
21	    try {
22	      if (typeof Notification === 'undefined') {
23	        onDone(false);
24	        return;
25	      }
26	      const res = await Notification.requestPermission();
27	      onDone(res === 'granted');
28	    } catch {
29	      onDone(false);
30	    } finally {
31	      setBusy(false);
32	    }
33	  };
34	
