71	  const [busy, setBusy] = useState<'buy' | 'restore' | null>(null);
72	  const [note, setNote] = useState<string | null>(null);
73	
74	  const buy = async () => {
75	    setBusy('buy');
76	    setNote(null);
77	    try {
78	      onDone(await purchase(plan));
79	    } finally {
80	      setBusy(null);
81	    }
82	  };
83	
84	  const restore = async () => {
85	    setBusy('restore');
86	    setNote(null);
