    entry.problems = problems;
    for (const problem of problems) run.problems.push(`${step}: ${problem}`);

    await handler.act(page, p, run);
    await expect(page.locator('.ob-root')).not.toHaveAttribute('data-step', step, { timeout: 20_000 });
