      await cta(page, 'Continue').click();
    },
  },

  reactions: {
    ready: async (page) =>
      void (await expect(heading(page, /Has anything you.ve taken not agreed with you/)).toBeVisible()),
    act: async (page, p) => {
      if (p.reactionsNote !== undefined && p.reactions !== null) {
