  recommendations: {
    ready: async (page) => {
      await expect(heading(page, 'What we found')).toBeVisible();
      await expect(page.locator('.ob-rec').first()).toBeVisible();
    },
    act: async (page, _p, run) => {
      for (const card of await page.locator('.ob-rec').all()) {
        run.recommendations.push({
