    },
  },
};

/* ── the loop ────────────────────────────────────────────────────────── */

/** Enough to walk the flow twice over; a loop that never ends fails loudly. */
const MAX_TRANSITIONS = 90;

export async function runPersona(page: Page, p: Persona): Promise<RunRecord> {
  const run: RunRecord = {
    persona: `${p.n}. ${p.name}`,
    screens: [],
    ms: 0,
    recommendations: [],
    leftOut: '',
    schedule: [],
    problems: [],
    notes: [],
  };

  await page.goto('/');
  const started = Date.now();
  /* Hooks fire once each. Two of these personas walk backwards, which means
     they see a screen twice — a hook that fired again on the second visit
     would put the run in a circle rather than through the branch. */
  const fired = new Set<string>();

  for (let moves = 0; moves < MAX_TRANSITIONS; moves++) {
    const step = await currentStep(page);
    if (step === null) break;
    const arrived = Date.now();

    const handler = HANDLERS[step];
    if (!handler) throw new Error(`no handler for step "${step}" — a screen was added to FLOW`);

    await handler.ready(page);
    const problems = await audit(page);
    const entry: ScreenRecord = { step, ms: 0, progress: await progressOf(page), problems };
    run.screens.push(entry);
    for (const problem of problems) run.problems.push(`${step}: ${problem}`);

    const hook = p.hooks?.[step];
    if (hook && !fired.has(step)) {
      fired.add(step);
      await hook(page, run);
    }
    // a hook that navigated owns the move; acting again would work the wrong screen
    if ((await currentStep(page)) === step) await handler.act(page, p, run);

    await expect(page.locator('.ob-root')).not.toHaveAttribute('data-step', step, { timeout: 20_000 });
    entry.ms = Date.now() - arrived;
  }

  run.ms = Date.now() - started;
  if (run.screens.length >= MAX_TRANSITIONS) {
    run.problems.push(`the flow never ended: ${MAX_TRANSITIONS} moves and still onboarding`);
  }
  return run;
}

/** The persisted store, as the app would read it back on a cold open. */
export async function readStore(page: Page): Promise<Record<string, unknown>> {
  return page.evaluate((key) => JSON.parse(localStorage.getItem(key) ?? '{}'), STORE_KEY);
}

/** Rewrite the store and reopen the app on it — a kill and a relaunch. */
export async function relaunch(page: Page, patch: Record<string, unknown> = {}): Promise<void> {
  await page.evaluate(
    ({ key, patch }) => {
      const cur = JSON.parse(localStorage.getItem(key) ?? '{}');
      localStorage.setItem(key, JSON.stringify({ ...cur, ...patch }));
    },
    { key: STORE_KEY, patch },
  );
  await page.reload();
}

/** One line per screen, for the report. */
export function timeline(run: RunRecord): string {
  return run.screens.map((s) => s.step).join(' → ');
}

import type { TestInfo } from '@playwright/test';
import { expect, test } from './support/app';
import { IRON_PRODUCT, B12_PRODUCT } from './support/catalogue';
import { readStore, relaunch, runPersona, timeline, type Persona, type RunRecord } from './support/persona';

/**
 * Twenty runs through onboarding — section 5 of PROMPT_PERSONALISATION.md.
 *
 * The point is not coverage for its own sake. Every one of these is a branch
 * that the happy path in `onboarding.spec.ts` walks straight past: a question
 * retired by an earlier answer, that same question re-opened by going back, a
 * store restored from a kill, a screen asked to hold fifteen chips or none.
 *
 * Each run records every screen in the order it was shown, how long it spent
 * on each, the recommendations it ended with, and anything that rendered
 * blank or was clipped by a container. That record is attached to the test, so
 * a failure comes with the whole run rather than one assertion.
 */

/* ── the shared answers ──────────────────────────────────────────────── */

/** Every persona answers these unless it says otherwise. */
const BASE: Omit<Persona, 'n' | 'name' | 'watch'> = {
  gender: 'Female',
  q1: 'None yet',
  q2: 'Once or twice',
  q3: 'I forget',
  goals: ['Sleep'],
  notifications: 'decline',
};

const persona = (p: Persona): Persona => ({ ...BASE, ...p });

/* ── running one ─────────────────────────────────────────────────────── */

/**
 * What every run is held to, whatever it answered: it ends in the app, it
 * ends with something to suggest, and nothing on the way was clipped or blank.
 */
async function report(run: RunRecord, info: TestInfo): Promise<void> {
  const lines = [
    `# ${run.persona}`,
    '',
    `${run.screens.length} screens, ${(run.ms / 1000).toFixed(1)}s`,
    '',
    '| screen | ms | progress | problems |',
    '| --- | --- | --- | --- |',
    ...run.screens.map(
      (s) => `| ${s.step} | ${s.ms} | ${s.progress ?? '—'} | ${s.problems.join('; ') || ''} |`,
    ),
    '',
    '## Recommendations',
    ...run.recommendations.map((r) => `- **${r.name}** — ${r.dose}${r.why ? `\n  - ${r.why}` : ''}`),
    '',
    '## What was left out',
    run.leftOut || '—',
    '',
    '## Schedule',
    ...run.schedule.map((s) => `- ${s.time} ${s.slot}: ${s.items.join(', ') || '(empty)'}`),
    '',
    '## Notes',
    ...(run.notes.length ? run.notes.map((n) => `- ${n}`) : ['- none']),
  ];
  await info.attach('run.md', { body: lines.join('\n'), contentType: 'text/markdown' });

  // the list reporter shows this, which is what makes twenty runs readable
  console.log(
    `${run.persona} · ${(run.ms / 1000).toFixed(1)}s · ${run.screens.length} screens · ` +
      `${run.recommendations.length} recs: ${run.recommendations.map((r) => r.name).join(', ')}`,
  );
  console.log(`   ${timeline(run)}`);
  for (const problem of run.problems) console.log(`   ! ${problem}`);
}

/** One run, reported, held to what every run is held to. */
async function walk(p: Persona, page: Parameters<typeof runPersona>[0], info: TestInfo): Promise<RunRecord> {
  const run = await runPersona(page, p);
  await report(run, info);

  expect(run.problems, 'clipped, blank or overflowing screens').toEqual([]);
  expect(run.recommendations.length, 'an empty recommendation list is a dead end').toBeGreaterThan(0);
  await expect(page.getByRole('heading', { name: 'Today' })).toBeVisible();
  return run;
}

